#include <stdint.h>
#include <string.h>
#define RCC_BASEADDR		(0x40023800)
#define SPI1_BASEADDR		(0x40013000)
#define RCC_APB2_CLOCK		(RCC_BASEADDR + 0x44)
#define RCC_AHB1_CLOCK		(RCC_BASEADDR + 0x30)
#define GPIOA_BASEADDR		(0x40020000)
#define GPIOB_BASEADDR		(0x40020400)

void delay()
{
	for(int i = 0; i < 500; i++);
}

uint32_t *Rcc_Ahb1_en =  (uint32_t *)RCC_AHB1_CLOCK;
uint32_t *Rcc_Apb2_en =  (uint32_t *)RCC_APB2_CLOCK;
uint32_t *spi1_cr1 = (uint32_t *)SPI1_BASEADDR;
uint32_t *spi1_cr2 = (uint32_t *)(SPI1_BASEADDR+0x04);
uint32_t *spi1_sr = (uint32_t *)(SPI1_BASEADDR+0x08);
uint32_t *spi1_dr = (uint32_t *)(SPI1_BASEADDR+0x0C);
uint32_t *spi1_crcpr = (uint32_t *)(SPI1_BASEADDR+0x10);
uint32_t *spi1_rxcrcr = (uint32_t *)(SPI1_BASEADDR+0x14);
uint32_t *spi1_txcrcr = (uint32_t *)(SPI1_BASEADDR+0x18);
uint32_t *gpioa_moder = (uint32_t *)GPIOA_BASEADDR;
