uint32_t *gpioa_afrl = (uint32_t *)(GPIOA_BASEADDR+0x20);

void SPIConfig (void)
{
	*Rcc_Apb2_en |= (1<<12);  // Enable SPI1 CLock

	*spi1_cr1 |= (1<<0);

	*spi1_cr1 &= ~(1<<1);   // CPOL=1, CPHA=1

	*spi1_cr1 |= (1<<2);  // Master Mode

	*spi1_cr1 |= (3<<3);  // BR[2:0] = 011: fPCLK/16, PCLK2 = 80MHz, SPI clk = 5MHz

	*spi1_cr1 &= ~(1<<7);  // LSBFIRST = 0, MSB first

	*spi1_cr1 |= (1<<8) | (1<<9);  // SSM=1, SSi=1 -> Software Slave Management

	//*spi1_cr1 &= ~(1<<8) | ~(1<<9);

	*spi1_cr1 &= ~(1<<10);  // RXONLY = 0, full-duplex

	*spi1_cr1 &= ~(1<<11);  // DFF=0, 8 bit data

}


void SPI_Transmit (uint8_t *data, int size)
{

	/************** STEPS TO FOLLOW *****************
	1. Wait for the TXE bit to set in the Status Register
	2. Write the data to the Data Register
	3. After the data has been transmitted, wait for the BSY bit to reset in Status Register
	4. Clear the Overrun flag by reading DR and SR
	************************************************/

	int i=0;
	while (size--)
	{
	   while (!((*spi1_sr)&(1<<1))){};  // wait for TXE bit to set -> This will indicate that the buffer is empty
	   *spi1_dr = *data;  // load the data into the Data Register
	   i++;
	   data++;
	   delay();
	}


/*During discontinuous communications, there is a 2 APB clock period delay between the
write operation to the SPI_DR register and BSY bit setting. As a consequence it is
mandatory to wait first until TXE is set and then until BSY is cleared after writing the last
data.
*/
	while (!((*spi1_sr)&(1<<1))) {};  // wait for TXE bit to set -> This will indicate that the buffer is empty
	while (((*spi1_sr)&(1<<7))) {};  // wait for BSY bit to Reset -> This will indicate that SPI is not busy in communication

	uint8_t temp =  *spi1_dr;
	temp = *spi1_sr;

}

void GPIOConfig (void)
{
	*Rcc_Ahb1_en |= (1<<0);  // Enable GPIO Clock

	*gpioa_moder |= (2<<10)|(2<<12)|(2<<14)|(1<<18);  // Alternate functions for PA5, PA6, PA7 and Output for PA9

	*gpioa_speed |= (2<<8)|(2<<10)|(2<<12)|(2<<14)|(2<<18);  // HIGH Speed for PA5, PA6, PA7, PA9

	*gpioa_afrl |= (5<<20)|(5<<24)|(5<<28);   // AF5(SPI1) for PA5, PA6, PA7
}

void SPI_Enable (void)
{
	*spi1_cr1 |= (1<<6);   // SPE=1, Peripheral enabled
	//*spi1_cr1 &= ~(1<<8);
}

void SPI_Disable (void)
{
	*spi1_cr1 &= ~(1<<6);   // SPE=0, Peripheral Disabled
	//*spi1_cr1 |= (1<<8);
}

void CS_Enable (void)
{
	*gpioa_odr &= ~(1<<9);
}

void CS_Disable (void)
{
	*gpioa_odr |= (1<<9);
}

uint8_t data[6] = {0x11, 0x12, 0x13, 0x14, 0x15, 0x16};

int main(void)
{
	GPIOConfig ();

	SPIConfig ();

	SPI_Enable();

	SPI_Transmit((uint8_t *)data, sizeof(data)/sizeof(*data));

	//SPI_Disable();


}


